using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using SparseFragments.Generator;

/// <summary>
/// Incremental step-tracking probe shared by the generator benchmarks
/// (issue #61). Counts tracked outputs that stay cached versus recompute so
/// wall-clock timings can be attributed to invalidation instead of noise.
/// "Recomputed" is any non-cached output, including value-equal reruns
/// (<c>Unchanged</c>); only <c>Modified</c>/<c>New</c> change generated bytes.
/// The same twelve stage names are pinned by the deterministic
/// <c>GeneratorStepTrackingTests</c> suite.
/// </summary>
internal static class GeneratorStepTracking
{
    public static readonly string[] TrackedStageNames =
    [
        "SparseFragmentsGenerator.Analysis",
        "SparseFragmentsGenerator.BclSetSupport",
        "SparseFragmentsGenerator.BlazorEditSessions",
        "SparseFragmentsGenerator.Output",
        "SparseFragmentsGenerator.PromotedPerRoot",
        "SparseFragmentsGenerator.PromotedContributions",
        "SparseFragmentsGenerator.ExplicitRoots",
        "SparseFragmentsGenerator.PromotedDedup",
        "SparseFragmentsGenerator.PromotedDistinct",
        "SparseFragmentsGenerator.Promoted",
        "SparseFragmentsGenerator.PromotedConflicts",
        "SparseFragmentsGenerator.IsExternalInit",
    ];

    public static GeneratorDriver CreateTrackedDriver() =>
        CSharpGeneratorDriver.Create(
            new ISourceGenerator[] { new SparseFragmentsGenerator().AsSourceGenerator() },
            driverOptions: new GeneratorDriverOptions(
                IncrementalGeneratorOutputKind.None,
                trackIncrementalGeneratorSteps: true
            )
        );

    public static int CachedOutputs(GeneratorRunResult result)
    {
        var cached = 0;
        foreach (var stage in TrackedStageNames)
        {
            if (!result.TrackedSteps.TryGetValue(stage, out var steps))
            {
                continue;
            }

            foreach (var step in steps)
            {
                foreach (var output in step.Outputs)
                {
                    if (output.Reason == IncrementalStepRunReason.Cached)
                    {
                        cached++;
                    }
                }
            }
        }

        return cached;
    }

    public static int RecomputedOutputs(GeneratorRunResult result)
    {
        var recomputed = 0;
        foreach (var stage in TrackedStageNames)
        {
            if (!result.TrackedSteps.TryGetValue(stage, out var steps))
            {
                continue;
            }

            foreach (var step in steps)
            {
                foreach (var output in step.Outputs)
                {
                    if (output.Reason != IncrementalStepRunReason.Cached)
                    {
                        recomputed++;
                    }
                }
            }
        }

        return recomputed;
    }

    public static int TotalSourceBytes(GeneratorRunResult result)
    {
        var bytes = 0;
        foreach (var source in result.GeneratedSources)
        {
            bytes += System.Text.Encoding.UTF8.GetByteCount(source.SourceText.ToString());
        }

        return bytes;
    }
}
